def _svd_full(X, r):
    """Exact top-r SVD of X as (U, S, S V^T). The numpy shims lack the flopscope `k=`
    extension; there the economy SVD is sliced, which is the same exact answer."""
    if _SVD_HAS_K:
        U, S, Vt = fnp.linalg.svd(X, full_matrices=False, k=r)
    else:
        U, S, Vt = fnp.linalg.svd(X, full_matrices=False)
        U, S, Vt = U[:, :r], S[:r], Vt[:r]
    return U, S, Vt * S[:, None]

