def _fz_g(tab, li):
    return tab[li] if li < len(tab) else None


def _fz_k2_rows(biv):
    """(row, side) of the closure rows that are k=2 marginal corrections: a D3/D4 marginal block on
    the side whose base Wick order (k - 3 for D3, k - 4 for D4) is 2."""
    out = []
    for i, (fs, ki, kj, cs) in enumerate(biv):
        for f in fs:
            if (f == 'D3i' and ki - 3 == 2) or (f == 'D4i' and ki - 4 == 2):
                out.append((i, 0))
            elif (f == 'D3j' and kj - 3 == 2) or (f == 'D4j' and kj - 4 == 2):
                out.append((i, 1))
    return out


def _gain1(tab, l, i):
    """tab[l][i], or exactly 1.0 past the table (shape-generic, hard rule 7)."""
    return tab[l][i] if l < len(tab) and i < len(tab[l]) else 1.0


def _gain2(tab, l, i, j):
    return tab[l][i][j] if l < len(tab) and i < len(tab[l]) and j < len(tab[l][i]) else 1.0

_CUR_LAYER = 0
_CUR_DEPTH = 1

_PCHIP_H = 1.0 / 3.0


def _pchip_end(d_near, d_far):
    """Shape-preserving one-sided end slope (Fritsch-Carlson)."""
    m = (3.0 * d_near - d_far) / 2.0
    if m * d_near <= 0.0:
        return 0.0
    if d_near * d_far <= 0.0 and abs(m) > abs(3.0 * d_near):
        return 3.0 * d_near
    return m


def _pchip4(knots, x):
    """Monotone cubic through 4 knots at x = 0, 1/3, 2/3, 1. Pure Python."""
    y0, y1, y2, y3 = knots
    if y0 == y1 == y2 == y3:
        return y0                      # EXACT, so a constant profile is identity
    if x <= 0.0:
        return y0
    if x >= 1.0:
        return y3
    d = ((y1 - y0) / _PCHIP_H, (y2 - y1) / _PCHIP_H, (y3 - y2) / _PCHIP_H)
    m = [0.0, 0.0, 0.0, 0.0]
    for _k in (1, 2):
        _a, _b = d[_k - 1], d[_k]
        m[_k] = 0.0 if _a * _b <= 0.0 else 2.0 / (1.0 / _a + 1.0 / _b)
    m[0] = _pchip_end(d[0], d[1])
    m[3] = _pchip_end(d[2], d[1])
    seg = 0 if x < _PCHIP_H else (1 if x < 2.0 * _PCHIP_H else 2)
    s = (x - seg * _PCHIP_H) / _PCHIP_H
    s2 = s * s
    s3 = s2 * s
    return ((2.0 * s3 - 3.0 * s2 + 1.0) * knots[seg]
            + (s3 - 2.0 * s2 + s) * _PCHIP_H * m[seg]
            + (-2.0 * s3 + 3.0 * s2) * knots[seg + 1]
            + (s3 - s2) * _PCHIP_H * m[seg + 1])


def _prof_at(name, i, depth):
    """Profile `name` at layer `i` of `depth`. Returns EXACTLY 1.0 when unset."""
    k = _COEFFS.get(name)
    if k is None:
        return 1.0
    x = 0.0 if depth <= 1 else float(i) / float(depth - 1)
    return _pchip4(k, x)


def _prof(name):
    """Profile `name` at the layer the chain is currently on."""
    return _prof_at(name, _CUR_LAYER, _CUR_DEPTH)


def _own_extra(x):
    th = _OWN_THETA_FAM * _prof("theta")
    if 0 <= _CUR_LAYER < len(_THETA_GAIN):
        th = th * _THETA_GAIN[_CUR_LAYER]
    return x if th == 1.0 else x * th


def _closure_apply(pK, cc, sigma, alpha, blocks, off_mask, last_layer, dtype, pp, H=None):
    """Add the declared closure's extra terms to `pK` in place. Returns `(H, nb)`."""
    prog = cc["prog"]
    if H is None:
        H = _closure_what(cc, sigma, alpha, dtype, pp)
    row = cc["row"]
    inv = 1.0 / sigma
    inv2 = inv * inv
    D3n = blocks["D3"] * (inv2 * inv)
    D4n = blocks["D4"] * (inv2 * inv2)
    uni_n = {"D3": D3n, "D4": D4n}
    # ---- univariate outputs -------------------------------------------------
    ups = (1,) if last_layer else (1, 2, 3, 4)
    # build-cost op diet (CLU): when every output p reads the same monomial list (true for the shipped
    # closure: D3^2, D3 D4, D4^2 for p = 1..4), form the monomials once and contract all p in ONE einsum
    # X[p,i] = sum_t Mu[t,i] H[row(k_t,p),i] c[p,t]; the finite guard and _own_extra act on the stack.
    _sels = [[(fs, k, cs[str(p)] * _gain2(_CU_GAIN, _CUR_LAYER, _u, p - 1))
              for _u, (fs, k, cs) in enumerate(prog["uni"]) if str(p) in cs] for p in ups]
    _fss = [tuple(fs) for fs, k, c in _sels[0]]
    if len(ups) > 1 and _fss and all([tuple(fs) for fs, k, c in sl] == _fss for sl in _sels):
        mons = []
        for fs in _fss:
            m = uni_n[fs[0]]
            for f in fs[1:]:
                m = m * uni_n[f]
            mons.append(m)
        Mu = fnp.stack(mons)
        Hs = fnp.stack([H[row[(k, p)]] for p, sl in zip(ups, _sels) for fs, k, c in sl]).reshape(
            len(ups), len(_fss), Mu.shape[1])
        cmat = fnp.array([[c for fs, k, c in sl] for sl in _sels], dtype=dtype)
        X = fnp.einsum("ti,pti,pt->pi", Mu, Hs, cmat)
        X = _own_extra(fnp.where(fnp.isfinite(X), X, dtype(0.0)))
        for _j, p in enumerate(ups):
            pK[(p,)] = pK[(p,)] + X[_j]
        ups = ()
    for p in ups:
        sel = [(fs, k, cs[str(p)] * _gain2(_CU_GAIN, _CUR_LAYER, _u, p - 1))
               for _u, (fs, k, cs) in enumerate(prog["uni"]) if str(p) in cs]
        if not sel:
            continue
        mons = []
        for fs, k, c in sel:
            m = uni_n[fs[0]]
            for f in fs[1:]:
                m = m * uni_n[f]
            mons.append(m)
        Mu = fnp.stack(mons)
        Hs = fnp.stack([H[row[(k, p)]] for fs, k, c in sel])
        cvec = fnp.array([c for fs, k, c in sel], dtype=dtype)
        X = fnp.einsum("ti,ti,t->i", Mu, Hs, cvec)
        X = fnp.where(fnp.isfinite(X), X, dtype(0.0))
        pK[(p,)] = pK[(p,)] + _own_extra(X)
    nb = None
    if last_layer or not prog["biv"]:
        return H, nb
    # ---- bivariate outputs, normalised blocks -------------------------------
    Cn = blocks["C11"] * (inv[:, None] * inv[None, :])
    D21n = blocks["D21"] * (inv2[:, None] * inv[None, :])
    D22n = blocks["D22"] * (inv2[:, None] * inv2[None, :])
    nb = {"C": Cn, "D21": D21n, "D12": D21n.T, "D22": D22n,
          "D3i": D3n[:, None], "D3j": D3n[None, :], "D4i": D4n[:, None], "D4j": D4n[None, :]}
    if "lam" in blocks and prog.get("has_q"):
        _t1 = _k4t1_on(_K4T1_B1, _K4T1_GQ, _CUR_LAYER)
        _t1g = _K4T1_GQ[_CUR_LAYER] if _t1 else 0.0
        if _t1:
            # Lane K9.1: kai's law, Q31n = b1 Cn + b2 D3n D21n (all uses of the slot together)
            _kai = Cn * _K4T1_B1[_CUR_LAYER] + (D3n[:, None] * D21n) * _K4T1_B2[_CUR_LAYER]
        if _t1g != 1.0:
            # kappa_iiij of the carried model kappa4 = m Sym(G (x) I), G = diag(dG) + lam C_off:
            # Q31_ij = (m/2) lam C_ij, normalised by s_i^3 s_j (Skeptic follow-up, 2026-09-17)
            nb["Q31"] = Cn * inv2[:, None] * (0.5 * blocks["metric"] * blocks["lam"])
            if blocks.get("metric_v") is not None:
                # forum item 1: Q31_ij = (m_i/2) lam C_ij with the per-neuron metric (overrides the line above,
                # which stays byte-identical for the refit adapter's anchors)
                nb["Q31"] = Cn * (inv2 * blocks["metric_v"])[:, None] * (0.5 * blocks["lam"])
            _q = _Q31_COEF[_CUR_LAYER] if _CUR_LAYER < len(_Q31_COEF) else None
            if _q is not None and any(c != 0.0 for c in _q):
                _gi = pp[0][:, None]
                nb["Q31"] = (nb["Q31"] + Cn * _q[0] + (Cn * Cn) * _q[1] + (_gi * Cn) * _q[2]
                             + (alpha[:, None] * alpha[None, :]) * _q[3] + _q[4])
            if _t1:
                nb["Q31"] = nb["Q31"] * _K4M_QS[_CUR_LAYER] + _kai   # Lane K9.1b mix
        else:
            nb["Q31"] = _kai
        nb["Q13"] = nb["Q31"].T
    mons = []
    for fs, ki, kj, cs in prog["biv"]:
        m = nb[fs[0]]
        for f in fs[1:]:
            m = m * nb[f]
        mons.append(m)
    biv = prog["biv"]
    _l = _CUR_LAYER
    _m2g, _m2c = _fz_g(_MARG2_GAIN, _l), _fz_g(_MARG2_C2_GAIN, _l)
    _c3g, _cqg = _fz_g(_CL_C3_GAIN, _l), _fz_g(_CL_CQ_GAIN, _l)
    if _fz_on(_m2g) or _fz_on(_m2c):
        _ind = fnp.where(alpha <= dtype(_MARG2_ALPHA), dtype(1.0), dtype(0.0))
    if _fz_on(_m2g):
        # forum item 2 (marg2): the k=2 corrections only in the dead tail, blended by the gain
        _gt = (_ind - 1.0) * _m2g + 1.0
        for _i, _side in _fz_k2_rows(biv):
            mons[_i] = mons[_i] * (_gt[:, None] if _side == 0 else _gt[None, :])
    _ext = []
    if _fz_on(_m2c) or _fz_on(_c3g):
        _C2 = Cn * Cn
    if _fz_on(_m2c):
        # 1/2 a2 b2 C^2 with a2 -> a2 + w5 t/6 + w6 k4/24 (each side), alpha <= -2 only
        # (the gain rides on the O(n) marginal vectors: coefficients stay Python floats)
        _d3g = (D3n * _ind) * _m2c
        _d4g = (D4n * _ind) * _m2c
        _ext += [(_C2 * _d3g[:, None], 5, 2, 1.0 / 12.0), (_C2 * _d3g[None, :], 2, 5, 1.0 / 12.0),
                 (_C2 * _d4g[:, None], 6, 2, 1.0 / 48.0), (_C2 * _d4g[None, :], 2, 6, 1.0 / 48.0)]
    if _fz_on(_c3g):
        # forum item 3: (1/6) a3 b3 C0^3
        _ext.append(((_C2 * Cn) * _c3g, 3, 3, 1.0 / 6.0))
    if _fz_on(_cqg) and "Q31" in nb:
        # forum item 3: (1/6) a4 b2 C0 K31 and its transpose
        _Cg = Cn * _cqg
        _ext += [(_Cg * nb["Q31"], 4, 2, 1.0 / 6.0), (_Cg * nb["Q13"], 2, 4, 1.0 / 6.0)]
    if _ext:
        biv = list(biv) + [(["ext"], _ki, _kj, {"11": _c, "21": _c, "22": _c}) for _m, _ki, _kj, _c in _ext]
        mons = mons + [_m for _m, _ki, _kj, _c in _ext]
    Mb = fnp.stack(mons)
    for out, sym in (((1, 1), True), ((2, 1), False), ((2, 2), True)):
        tag = "%d%d" % out
        sel = [(i, ki, kj, cs[tag] * _gain1(_CB_GAIN, _CUR_LAYER, i))
               for i, (fs, ki, kj, cs) in enumerate(biv) if tag in cs]
        if not sel:
            continue
        Mt = Mb if len(sel) == len(biv) else fnp.stack([mons[i] for i, *_ in sel])
        Li = fnp.stack([H[row[(ki, out[0])]] for i, ki, kj, c in sel])
        Rj = (fnp.stack([H[row[(kj, out[1])]] for i, ki, kj, c in sel])
              * fnp.array([[c] for i, ki, kj, c in sel], dtype=dtype))
        X = fnp.einsum("tij,ti,tj->ij", Mt, Li, Rj)
        X = fnp.nan_to_num(X, nan=0.0, posinf=0.0, neginf=0.0)
        if sym:
            X = (X + X.T) * 0.5
        pK[out] = pK[out] + _own_extra(X) * off_mask
    return H, nb


def _protect_factors(cc, H, sigma, dG, D3, metric, pk1, dtype):
    """Exact (U, V), (n, q) each, with the D22-driven K21 content = (U V^T) before the diagonal kill."""
    row = cc["row"]
    inv = 1.0 / sigma
    inv2 = inv * inv
    atoms = {"is2": inv2, "dGn": dG * inv2, "D3n": D3 * (inv2 * inv),
             "D4n": (dG * metric) * (inv2 * inv2)}
    Us, Vs = [], []
    for col in cc["prog"]["protect"]:
        v = H[row[tuple(col["v_w"])]]
        for a in col["v"]:
            v = v * atoms[a]
        u = None
        for ut in col["u_terms"]:
            t = H[row[tuple(ut["u_w"])]] * (ut["coef"] * (metric / 6.0) ** ut["d22_count"])
            for a in ut["u"]:
                t = t * atoms[a]
            if ut["times_m2pk1"]:
                t = t * (pk1 * (-2.0))
            u = t if u is None else u + t
        Us.append(u)
        Vs.append(v)
    return fnp.stack(Us, axis=1), fnp.stack(Vs, axis=1)


